import axiosClient from "./axiosConfig";


const bannerService = {
  // Lấy banner hiển thị ngoài trang chủ
  getActive: () => axiosClient.get(`banners/active`),
  
  // Các hàm quản lý cho Admin
  getAllAdmin: () => axiosClient.get(`${API_URL}/admin/all`),
  create: (data) => axiosClient.post(API_URL, data),
  update: (id, data) => axiosClient.put(`${API_URL}/${id}`, data),
  toggleVisibility: (id) => axiosClient.put(`${API_URL}/${id}/toggle`),
  delete: (id) => axiosClient.delete(`${API_URL}/${id}`),
};

export default bannerService;
